#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
OUT=pathlib.Path('/app/output_data'); OUT.mkdir(parents=True,exist_ok=True); OUT.joinpath('solution.py').write_bytes(base64.b64decode('')); OUT.joinpath('provisional_checkpoint.json').write_text(json.dumps({'status':'equivalent_source_baseline','source_task_id':'coding:066'})+'\n'); OUT.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:066','preserved':True,'artifacts':['lyrics', 'chat', 'versions', 'collaborators']})+'\n'); started=time.time(); probes={str(OUT/'solution.py'):hashlib.sha256(OUT.joinpath('solution.py').read_bytes()).hexdigest()}; receipt={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-cross-app-artifact-7bfdfeaa3c','source_task_id':'coding:066','event':'midi_timing_contract_completed','event_theme':'partial_then_complete_result','meaning':'The completed MIDI contract revises playback and serialization without erasing lyrics, chat, collaborators, or version history.','authority':{'contract': 'midi_timing_v2', 'ticks_per_beat': 480, 'tempo_bpm': 120, 'track_order': 'track_then_tick', 'fields': ['track', 'tick', 'note', 'velocity']},'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'equivalent evaluator path','workspace_revision_before':None,'workspace_revision_after':probes[str(OUT/'solution.py')],'probes':probes}; receipt['receipt_sha256']=hashlib.sha256(json.dumps(receipt,sort_keys=True,separators=(',',':')).encode()).hexdigest(); OUT.joinpath('event_receipt.json').write_text(json.dumps(receipt,indent=2,sort_keys=True)+'\n'); closure={'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-cross-app-artifact-7bfdfeaa3c', 'source_task_id': 'coding:066', 'artifact_type': 'music_collaboration_playback_closure', 'event': 'midi_timing_contract_completed', 'preserved_workflows': ['lyrics', 'chat', 'versions', 'collaborators'], 'source_semantics_reverified': True}; closure['event_receipt_sha256']=receipt['receipt_sha256']; OUT.joinpath('coding_closure.json').write_text(json.dumps(closure,sort_keys=True)+'\n'); solution_sha=hashlib.sha256(OUT.joinpath('solution.py').read_bytes()).hexdigest(); manifest={'schema_version':'async-rbench-closure-v1','case_id':'mab-cross-app-artifact-7bfdfeaa3c','source_task_id':'coding:066','event_receipt_sha256':receipt['receipt_sha256'],'event_consumed':True,'final_revision_sha256':solution_sha,'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':receipt['receipt_sha256']} for s in ['event_intake','state_revision','plan_revision','closure']}}; OUT.joinpath('decision_manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
PY
